import React, { useState } from "react";
import CustomerOrderItem from "../../../models/customerOrderItem";
import MyItem from "../../../models/myItem";

export default function ItemsSummary({ data }) {
  let itemNamesArray = [];
  let itemNamesArrayFiltered = [];
  let itemsArray = [];
  let itemsArrayFiltered = [];
  let filtered = [];
  let categoryValue = 0.0;

  if (data && data.length) {
    data.map((x) => {
      if (x.items && x.items.length) {
        x.items.map((item) => {
          const myItem = new MyItem(
            item.id,
            item.title,
            item.quantity,
            item.price,
            item.ticket,
            item.charge
          );
          console.log("fddfdf", myItem);
          itemsArray.push(myItem);
        });
      }
    });
  }
  let i = 2;
  let len = itemsArray.length;
  let text = "";
  for (; i < len; i++) {
    text = itemsArray[i]["title"];
    itemNamesArray.push(text);
  }

  console.log("itemNamesArray", itemNamesArray);

  const removeDuplicates = (arr) => {
    return [...new Set(arr)];
  };

  if (itemNamesArray.length > 0) {
    itemNamesArrayFiltered = removeDuplicates(itemNamesArray);
    console.log("itemNamesArrayFiltered", itemNamesArrayFiltered);
  }

  let uniq = itemNamesArray.reduce(function (a, b) {
    if (a.indexOf(b) < 0) a.push(b);
    return a;
  }, []);

  console.log("unique", uniq);

  itemNamesArrayFiltered = removeDuplicates(itemNamesArray);

  return (
    <div>
      <p className="text-xl font-bold">ITEMS SUMMARY</p>
      <div className="grid grid-cols-4 w-full font-semibold  justify-around">
        {uniq.map((name) => {
          filtered = itemsArray.filter((x) => x.title === name);
          let categoryValue = 0.0;
          let categoryQuantity = 0.0;
          let itemPrice = 0.0;
          filtered.map((fil) => {
            categoryValue = categoryValue + fil.quantity * fil.price;

            console.log("categoryValue", categoryValue);
            categoryQuantity = categoryQuantity + fil.quantity;
            itemPrice = parseFloat(fil.price).toFixed(2);
          });
          return (
            <p>
              <span>{categoryQuantity}</span>
              <span>x</span>
              <span>{name}</span>
              <span>@{itemPrice}</span>
              <span>-</span>
              <span className="">
                KES {parseFloat(categoryValue).toFixed(2)}
              </span>
            </p>
          );
        })}
      </div>
    </div>
  );
}
